I-3.5.3 年次データの結合

annual_data &lt;- annual_stock_data |&gt;
  left_join(
    financial_data,
    by = c("firm_ID", "year")
  ) |&gt;
  arrange(firm_ID, year)

stopifnot(
  nrow(annual_data) ==
    nrow(annual_stock_data)
)

annual_data_overview &lt;- annual_data |&gt;
  summarise(
    observations = n(),
    firms = n_distinct(firm_ID),
    first_year = min(year, na.rm = TRUE),
    last_year = max(year, na.rm = TRUE),
    financial_matches =
      sum(!is.na(BE))
  )

