I-3.5.4 月次データへの財務情報の付加

monthly_data &lt;- stock_data |&gt;
  left_join(
    financial_data,
    by = c("firm_ID", "year")
  ) |&gt;
  arrange(firm_ID, month_ID)

stopifnot(
  nrow(monthly_data) ==
    nrow(stock_data)
)

row_count_check &lt;- tibble(
  stock_rows = nrow(stock_data),
  monthly_rows = nrow(monthly_data),
  annual_rows = nrow(annual_data)
)

