I-3.6.3 年度別回帰
年度ごとの回帰をnest()とpurrr::map()で実行する。

yearly_regression_models &lt;- annual_data |&gt;
  filter(
    is.finite(Re),
    is.finite(lagged_BEME)
  ) |&gt;
  group_by(year) |&gt;
  filter(n() &gt;= 30) |&gt;
  ungroup() |&gt;
  nest(data = -year) |&gt;
  mutate(
    model = map(
      data,
      \(data) lm(
        Re ~ lagged_BEME,
        data = data
      )
    ),
    coefficients = map(
      model,
      broom::tidy
    ),
    fit = map(
      model,
      broom::glance
    )
  )


yearly_regression_coefficients &lt;-
  yearly_regression_models |&gt;
  select(year, coefficients) |&gt;
  unnest(coefficients) |&gt;
  arrange(year, term)

yearly_regression_fit &lt;-
  yearly_regression_models |&gt;
  select(year, fit) |&gt;
  unnest(fit) |&gt;
  select(
    year,
    r.squared,
    adj.r.squared,
    sigma,
    statistic,
    p.value,
    nobs
  ) |&gt;
  arrange(year)

show_table_LFL(
  yearly_regression_coefficients,
  n = nrow(yearly_regression_coefficients)
)
